        elif supply >= 18:
            base = max(base, avg_prev * 0.6)
        else:
            base = max(base, max_prev * 0.72)

    if rich_aggressive >= 2 and supply <= 19 and hp >= 5 and no_water == 0:
        base *= 0.7

